
from scapy.all import *


class TWAMP(Packet):
    sequence_number = 0
    name = "Two Way Active Measurement Protocol"
    fields_desc = [ IntField("sequence", 0),
                    IntField("Time_integer", 0),
            IntField("Time_fraction",0 ),
            XShortField("Error_Estimate",0x0005),
            BitField("Padding", 0, 58*8)
            ]

    def __init__(self, **fields):
        fields["sequence"] = self._get_sequence_number_of_packet()
        super(TWAMP, self).__init__(**fields)

    def _get_sequence_number_of_packet(self):
        TWAMP.sequence_number += 1
        return TWAMP.sequence_number


if __name__ == "__main__":
    interact(mydict=globals(), mybanner="TWAMP added...")


